/* prog25_balanced_multitype.c
 *
 * Re‑implementation of the original binary's behaviour:
 *   - Takes at most one command‑line argument.
 *   - Checks that the argument contains a correctly balanced sequence of
 *     parentheses '()', square brackets '[]' and curly braces '{}'.
 *   - Prints "BALANCED" if the sequence is balanced, otherwise "UNBALANCED".
 *   - If no argument is supplied the program also prints "BALANCED".
 *
 * The algorithm uses a simple stack stored in a fixed‑size array.
 * The original binary limited the stack to 511 entries; we keep the same
 * limit for compatibility, but any reasonable input will be far smaller.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_STACK 512   /* matches the original binary's 0x1ff limit */

int main(int argc, char *argv[])
{
    const char *input;
    size_t len, i;
    char stack[MAX_STACK];
    int sp = 0;               /* stack pointer */
    int balanced = 1;         /* assume balanced until a mismatch is found */

    /* No argument -> automatically balanced (original behaviour) */
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }

    input = argv[1];
    len = strlen(input);

    for (i = 0; i < len && balanced; ++i) {
        char c = input[i];

        switch (c) {
            /* opening characters – push onto the stack */
            case '(':
            case '[':
            case '{':
                if (sp >= MAX_STACK) {          /* overflow – treat as unbalanced */
                    balanced = 0;
                } else {
                    stack[sp++] = c;
                }
                break;

            /* closing characters – pop and compare */
            case ')':
                if (sp == 0 || stack[sp-1] != '(') balanced = 0;
                else sp--;
                break;
            case ']':
                if (sp == 0 || stack[sp-1] != '[') balanced = 0;
                else sp--;
                break;
            case '}':
                if (sp == 0 || stack[sp-1] != '{') balanced = 0;
                else sp--;
                break;

            /* any other character is ignored – the original program never
               examined characters outside the three bracket types. */
            default:
                break;
        }
    }

    /* If there are still items on the stack, the string is unbalanced */
    if (sp != 0) balanced = 0;

    puts(balanced ? "BALANCED" : "UNBALANCED");
    return 0;
}
